package main
import("testing";"net/http/httptest";"strings";"os";"path/filepath")
func TestExistingSSLStateSurvivesFailedCertificateAttempt(t *testing.T){store,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};site:=Site{ID:"ssl-fixture",Domain:"example.test",SSL:true};store.cfg.Sites=[]Site{site};app:=&App{store:store,system:&System{demo:true}};response:=httptest.NewRecorder();app.enableSSL(response,httptest.NewRequest("POST","/api/sites/ssl",strings.NewReader(`{"id":"ssl-fixture","email":"invalid"}`)));if response.Code==200{t.Fatal("invalid certificate request succeeded")};if !store.SiteByID(site.ID).SSL{t.Fatal("failed certificate attempt cleared existing SSL status")}}
func TestFirstWebsiteMailboxCreatesDomainAtomically(t *testing.T){store,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};store.cfg.Sites=[]Site{{ID:"mail-fixture",Domain:"example.test"}};app:=&App{store:store,system:&System{demo:true}}
 call:=func(body string)int{response:=httptest.NewRecorder();app.createMailbox(response,httptest.NewRequest("POST","/api/mail/mailboxes",strings.NewReader(body)));return response.Code}
 if call(`{"domain":"example.test","localPart":"admin","password":"short","quotaMb":2048}`)!=400{t.Fatal("invalid password accepted")};domains,mailboxes,_:=store.MailConfig();if len(domains)!=0||len(mailboxes)!=0{t.Fatal("failed mailbox creation enabled mail routing")}
 if call(`{"domain":"example.test","localPart":"admin","password":"valid-fixture-password-28","quotaMb":2048}`)!=201{t.Fatal("valid website mailbox failed")};domains,mailboxes,_=store.MailConfig();if len(domains)!=1||len(mailboxes)!=1{t.Fatal("first mailbox/domain were not committed together")}
 reopened,err:=OpenStore(filepath.Dir(store.path));if err!=nil{t.Fatal(err)};domains,mailboxes,_=reopened.MailConfig();if len(domains)!=1||len(mailboxes)!=1{t.Fatal("mail state not persisted")}
 if call(`{"domain":"foreign.test","localPart":"admin","password":"valid-fixture-password-28","quotaMb":2048}`)!=400{t.Fatal("unregistered non-website mail domain accepted")}}
func TestMailboxDomainTransactionRollsBackFailedSave(t *testing.T){store,err:=OpenStore(t.TempDir());if err!=nil{t.Fatal(err)};blocked:=filepath.Join(t.TempDir(),"not-a-directory");if err=os.WriteFile(blocked,[]byte("fixture"),0600);err!=nil{t.Fatal(err)};store.path=filepath.Join(blocked,"config.json");err=store.AddMailboxWithDomain(Mailbox{Address:"admin@example.test"},&MailDomain{Domain:"example.test"});if err==nil{t.Fatal("save unexpectedly succeeded")};domains,mailboxes,_:=store.MailConfig();if len(domains)!=0||len(mailboxes)!=0{t.Fatal("failed save partially committed mail state")}}
